      <div data-testid="summary-item" class="summary-item">
        <span data-testid="summary-item-title">{{ row.title }}</span>
        <span data-testid="summary-item-datetime">{{ row.datetime }}</span>
        <span data-testid="summary-item-row">{{ row.unit.row }}</span>
        <span data-testid="summary-item-seat">{{ row.seatDescription }}</span>
