export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

export interface ReservationCustomer {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
}

export interface Reservation {
  id: number;
  screeningId: number;
  seats: string[];
  customer: ReservationCustomer;
  totalPrice: number;
}

export interface ReservationRequest {
  screeningId: number;
  seats: string[];
  customer: ReservationCustomer;
  totalPrice: number;
}

export const MAX_SEATS = 10;
export const COUCH_ROW = 15;

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function parseSeatId(id: string): { row: number; column: number } {
  const match = /^R(\d+)C(\d+)$/.exec(id);
  if (!match) {
    throw new Error(`Invalid seat id: ${id}`);
  }
  return { row: Number(match[1]), column: Number(match[2]) };
}

export function rowPrice(row: number): number {
  if (row <= 5) return 25;
  if (row <= 10) return 32;
  if (row <= 14) return 39;
  return 89;
}

export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

export interface SelectionUnit {
  row: number;
  columnStart: number;
  columnEnd?: number;
  ids: string[];
  isCouch: boolean;
  price: number;
}

/** Groups a flat list of seat identifiers into seats/couches, ordered by row then column. */
export function buildUnits(seats: string[]): SelectionUnit[] {
  const byRow = new Map<number, number[]>();
  for (const id of seats) {
    const { row, column } = parseSeatId(id);
    const columns = byRow.get(row) ?? [];
    columns.push(column);
    byRow.set(row, columns);
  }

  const units: SelectionUnit[] = [];
  const rows = [...byRow.keys()].sort((a, b) => a - b);
  for (const row of rows) {
    const columns = [...byRow.get(row)!].sort((a, b) => a - b);
    if (row === COUCH_ROW) {
      for (let i = 0; i < columns.length; i += 2) {
        const start = columns[i];
        const end = columns[i + 1];
        units.push({
          row,
          columnStart: start,
          columnEnd: end,
          ids: [seatId(row, start), seatId(row, end)],
          isCouch: true,
          price: rowPrice(row),
        });
      }
    } else {
      for (const column of columns) {
        units.push({
          row,
          columnStart: column,
          ids: [seatId(row, column)],
          isCouch: false,
          price: rowPrice(row),
        });
      }
    }
  }
  return units;
}

export interface SelectionRowGroup {
  row: number;
  label: string;
}

export function groupSelectionByRow(seats: string[]): SelectionRowGroup[] {
  return buildUnits(seats).reduce<SelectionRowGroup[]>((groups, unit) => {
    const label = unit.isCouch ? `${unit.columnStart}-${unit.columnEnd}` : `${unit.columnStart}`;
    const last = groups[groups.length - 1];
    if (last && last.row === unit.row) {
      last.label = `${last.label}, ${label}`;
    } else {
      groups.push({ row: unit.row, label });
    }
    return groups;
  }, []);
}

export function orderedSeatIds(seats: string[]): string[] {
  return buildUnits(seats).flatMap((unit) => unit.ids);
}

export function totalPrice(seats: string[]): number {
  return buildUnits(seats).reduce((sum, unit) => sum + unit.price, 0);
}

import { seatId } from './seat-utils';

export type CellState = 'available' | 'selected' | 'unavailable' | 'accessible';

export interface SeatCellView {
  kind: 'seat';
  row: number;
  column: number;
  state: CellState;
}

export interface CouchCellView {
  kind: 'couch';
  row: number;
  columnStart: number;
  columnEnd: number;
  state: CellState;
}

export interface GapCellView {
  kind: 'entrance' | 'aisle';
}

export type CellView = SeatCellView | CouchCellView | GapCellView;

export interface RowView {
  row: number;
  cells: CellView[];
}

const ACCESSIBLE_COLUMNS = new Set([10, 11, 12, 13, 14, 15]);
const TOTAL_ROWS = 15;
const COUCH_ROW = 15;

function seatState(row: number, column: number, occupied: ReadonlySet<string>, selected: ReadonlySet<string>): CellState {
  const id = seatId(row, column);
  if (selected.has(id)) return 'selected';
  if (occupied.has(id)) return 'unavailable';
  if (row === 1 && ACCESSIBLE_COLUMNS.has(column)) return 'accessible';
  return 'available';
}

function couchState(row: number, start: number, end: number, occupied: ReadonlySet<string>, selected: ReadonlySet<string>): CellState {
  const idA = seatId(row, start);
  const idB = seatId(row, end);
  if (selected.has(idA) || selected.has(idB)) return 'selected';
  if (occupied.has(idA) || occupied.has(idB)) return 'unavailable';
  return 'available';
}

function seatCell(row: number, column: number, occupied: ReadonlySet<string>, selected: ReadonlySet<string>): SeatCellView {
  return { kind: 'seat', row, column, state: seatState(row, column, occupied, selected) };
}

function couchCell(row: number, start: number, end: number, occupied: ReadonlySet<string>, selected: ReadonlySet<string>): CouchCellView {
  return { kind: 'couch', row, columnStart: start, columnEnd: end, state: couchState(row, start, end, occupied, selected) };
}

export function buildAuditorium(occupied: ReadonlySet<string>, selected: ReadonlySet<string>): RowView[] {
  const rows: RowView[] = [];
  for (let row = 1; row <= TOTAL_ROWS; row++) {
    const cells: CellView[] = [];
    const isCouchRow = row === COUCH_ROW;
    const hasLeftBlock = row >= 11;

    if (hasLeftBlock) {
      if (isCouchRow) {
        cells.push(couchCell(row, 1, 2, occupied, selected));
        cells.push(couchCell(row, 3, 4, occupied, selected));
      } else {
        for (let c = 1; c <= 4; c++) cells.push(seatCell(row, c, occupied, selected));
      }
    } else {
      cells.push({ kind: 'entrance' });
    }

    cells.push({ kind: 'aisle' });

    if (isCouchRow) {
      for (let c = 5; c <= 19; c += 2) cells.push(couchCell(row, c, c + 1, occupied, selected));
    } else {
      for (let c = 5; c <= 20; c++) cells.push(seatCell(row, c, occupied, selected));
    }

    cells.push({ kind: 'aisle' });

    if (isCouchRow) {
      cells.push(couchCell(row, 21, 22, occupied, selected));
      cells.push(couchCell(row, 23, 24, occupied, selected));
    } else {
      for (let c = 21; c <= 24; c++) cells.push(seatCell(row, c, occupied, selected));
    }

    rows.push({ row, cells });
  }
  return rows;
}

const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

export function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

export function addDays(date: Date, days: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

export function isoDate(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

export function parseIsoDate(value: string): Date | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) return null;
  return date;
}

export function weekdayName(date: Date): string {
  return WEEKDAYS[date.getDay()];
}

/** `<Weekday> <D> <Mon> <HH:mm>`, e.g. `Tuesday 15 Sep 16:00`. */
export function showDate(isoDateValue: string, time: string): string {
  const date = parseIsoDate(isoDateValue);
  if (!date) return '';
  return `${weekdayName(date)} ${date.getDate()} ${MONTHS[date.getMonth()]} ${time}`;
}

/** Resolves the day picker's selected date from the `date` query param: missing, invalid or past selects today. */
export function resolveSelectedDate(param: string | null): Date {
  const today = startOfDay(new Date());
  if (!param) return today;
  const parsed = parseIsoDate(param);
  if (!parsed || parsed.getTime() < today.getTime()) return today;
  return parsed;
}

import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Movie, Reservation, ReservationRequest, Screening } from './models';

const BASE_URL = 'http://localhost:3000';

@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient);

  getMovies(): Observable<Movie[]> {
    return this.http.get<Movie[]>(`${BASE_URL}/movies`);
  }

  getScreeningsByDate(date: string): Observable<Screening[]> {
    return this.http.get<Screening[]>(`${BASE_URL}/screenings`, { params: new HttpParams().set('date', date) });
  }

  getScreening(id: number): Observable<Screening> {
    return this.http.get<Screening>(`${BASE_URL}/screenings/${id}`);
  }

  createReservation(request: ReservationRequest): Observable<Reservation> {
    return this.http.post<Reservation>(`${BASE_URL}/reservations`, request);
  }
}

import { Injectable, signal } from '@angular/core';

export interface CheckoutFormValues {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  termsAccepted: boolean;
}

export interface BookingState {
  screeningId: number;
  seats: string[];
  form: CheckoutFormValues;
  paid: boolean;
  email: string | null;
}

const STORAGE_KEY = 'cinescope-booking';

function emptyForm(): CheckoutFormValues {
  return { firstName: '', lastName: '', email: '', confirmEmail: '', phone: '', termsAccepted: false };
}

@Injectable({ providedIn: 'root' })
export class BookingService {
  private readonly state = signal<BookingState | null>(this.load());

  readonly booking = this.state.asReadonly();

  private load(): BookingState | null {
    try {
      const raw = sessionStorage.getItem(STORAGE_KEY);
      return raw ? (JSON.parse(raw) as BookingState) : null;
    } catch {
      return null;
    }
  }

  private persist(next: BookingState | null): void {
    this.state.set(next);
    if (next) {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(next));
    } else {
      sessionStorage.removeItem(STORAGE_KEY);
    }
  }

  /** Starts a fresh, empty booking for this screening unless one for it is already in progress. */
  ensureBookingFor(screeningId: number): void {
    const current = this.state();
    if (current && current.screeningId === screeningId && !current.paid) return;
    this.persist({ screeningId, seats: [], form: emptyForm(), paid: false, email: null });
  }

  belongsToUnpaid(screeningId: number): boolean {
    const current = this.state();
    return !!current && !current.paid && current.screeningId === screeningId;
  }

  isPaid(): boolean {
    return !!this.state()?.paid;
  }

  setSeats(seats: string[]): void {
    const current = this.state();
    if (!current) return;
    this.persist({ ...current, seats });
  }

  updateForm(partial: Partial<CheckoutFormValues>): void {
    const current = this.state();
    if (!current) return;
    this.persist({ ...current, form: { ...current.form, ...partial } });
  }

  markPaid(email: string): void {
    const current = this.state();
    if (!current) return;
    this.persist({ ...current, paid: true, email });
  }

  clear(): void {
    this.persist(null);
  }
}

