// Minimal CDP driver using Node's built-in fetch/WebSocket.
const BASE = 'http://localhost:9222';

async function newTab(url) {
  const res = await fetch(`${BASE}/json/new?${encodeURIComponent(url)}`, { method: 'PUT' });
  return res.json();
}

function connect(wsUrl) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(wsUrl);
    ws.addEventListener('open', () => resolve(ws));
    ws.addEventListener('error', reject);
  });
}

function send(ws, method, params = {}) {
  return new Promise((resolve) => {
    const id = Math.floor(Math.random() * 1e9);
    const handler = (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id === id) {
        ws.removeEventListener('message', handler);
        resolve(msg.result);
      }
    };
    ws.addEventListener('message', handler);
    ws.send(JSON.stringify({ id, method, params }));
  });
}

async function evaluate(ws, expression) {
  const result = await send(ws, 'Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (result.exceptionDetails) {
    throw new Error(JSON.stringify(result.exceptionDetails));
  }
  return result.result.value;
}

async function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

module.exports = { newTab, connect, send, evaluate, sleep };

const { newTab, connect, send, evaluate, sleep } = require('/tmp/cdp.js');

async function main() {
  const tab = await newTab('http://localhost:4200/');
  const ws = await connect(tab.webSocketDebuggerUrl);

  const consoleErrors = [];
  const failedRequests = [];
  ws.addEventListener('message', (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.method === 'Runtime.consoleAPICalled' && (msg.params.type === 'error' || msg.params.type === 'warning')) {
      const text = (msg.params.args || []).map((a) => a.value ?? a.description).join(' ');
      consoleErrors.push(`[${msg.params.type}] ${text}`);
    }
    if (msg.method === 'Network.loadingFailed') {
      failedRequests.push(`FAILED ${msg.params.errorText} ${msg.params.requestId}`);
    }
  });

  await send(ws, 'Runtime.enable');
  await send(ws, 'Network.enable');
  await send(ws, 'Page.enable');

  await sleep(1500);

  const homeState = await evaluate(ws, `
    (() => {
      const loading = !!document.querySelector('[data-testid="movies-loading"]');
      const error = document.querySelector('[data-testid="movies-error"]')?.textContent || null;
      const empty = document.querySelector('[data-testid="movies-empty"]')?.textContent || null;
      const cards = [...document.querySelectorAll('[data-testid="movie-card"]')].map(c => ({
        id: c.getAttribute('data-movie-id'),
        title: c.querySelector('[data-testid="movie-title"]')?.textContent,
        screenings: [...c.querySelectorAll('[data-testid="screening-button"]')].map(b => ({ id: b.getAttribute('data-screening-id'), time: b.textContent.trim() })),
      }));
      const dayButtons = [...document.querySelectorAll('[data-testid="day-button"]')].map(b => ({ date: b.getAttribute('data-date'), selected: b.getAttribute('data-selected'), label: b.textContent.trim() }));
      return { loading, error, empty, cards, dayButtons, url: location.href };
    })()
  `);
  console.log('HOME STATE:', JSON.stringify(homeState, null, 2));

  if (homeState.cards.length === 0) {
    console.log('No movie cards found on first day; cannot continue flow.');
    console.log('CONSOLE:', consoleErrors);
    process.exit(0);
  }

  const screeningId = homeState.cards[0].screenings[0].id;
  await evaluate(ws, `document.querySelector('[data-testid="screening-button"][data-screening-id="${screeningId}"]').click()`);
  await sleep(1000);

  const seatMapState = await evaluate(ws, `
    (() => {
      const title = document.querySelector('[data-testid="seat-map-title"]')?.textContent;
      const subtitle = document.querySelector('[data-testid="seat-map-subtitle"]')?.textContent;
      const seats = document.querySelectorAll('[data-testid="seat"]').length;
      const couches = document.querySelectorAll('[data-testid="couch"]').length;
      const availableSeat = document.querySelector('[data-testid="seat"][data-state="available"]');
      const availableCouch = document.querySelector('[data-testid="couch"][data-state="available"]');
      return {
        url: location.href, title, subtitle, seats, couches,
        availableSeat: availableSeat ? { row: availableSeat.getAttribute('data-row'), column: availableSeat.getAttribute('data-column') } : null,
        availableCouch: availableCouch ? { row: availableCouch.getAttribute('data-row'), start: availableCouch.getAttribute('data-column-start') } : null,
      };
    })()
  `);
  console.log('SEAT MAP STATE:', JSON.stringify(seatMapState, null, 2));

  // select the available seat and the available couch
  await evaluate(ws, `document.querySelector('[data-testid="seat"][data-row="${seatMapState.availableSeat.row}"][data-column="${seatMapState.availableSeat.column}"]').click()`);
  await evaluate(ws, `document.querySelector('[data-testid="couch"][data-row="${seatMapState.availableCouch.row}"][data-column-start="${seatMapState.availableCouch.start}"]').click()`);
  await sleep(300);

  const panelState = await evaluate(ws, `
    (() => {
      const count = document.querySelector('[data-testid="selected-seats-count"]')?.textContent;
      const rows = [...document.querySelectorAll('[data-testid="selected-seats-row"]')].map(r => r.textContent);
      return { count, rows };
    })()
  `);
  console.log('PANEL STATE:', JSON.stringify(panelState, null, 2));

  await evaluate(ws, `document.querySelector('[data-testid="continue-button"]').click()`);
  await sleep(800);

  const summaryState = await evaluate(ws, `
    (() => {
      const title = document.querySelector('[data-testid="summary-title"]')?.textContent;
      const items = [...document.querySelectorAll('[data-testid="summary-item"]')].map(i => ({
        title: i.querySelector('[data-testid="summary-item-title"]')?.textContent,
        datetime: i.querySelector('[data-testid="summary-item-datetime"]')?.textContent,
        row: i.querySelector('[data-testid="summary-item-row"]')?.textContent,
        seat: i.querySelector('[data-testid="summary-item-seat"]')?.textContent,
        price: i.querySelector('[data-testid="summary-item-price"]')?.textContent,
      }));
      const total = document.querySelector('[data-testid="summary-total"]')?.textContent;
      return { url: location.href, title, items, total };
    })()
  `);
  console.log('SUMMARY STATE:', JSON.stringify(summaryState, null, 2));

  await evaluate(ws, `document.querySelector('[data-testid="confirm-button"]').click()`);
  await sleep(800);

  const checkoutUrl = await evaluate(ws, `location.href`);
  console.log('CHECKOUT URL:', checkoutUrl);

  // fill the checkout form
  await evaluate(ws, `
    (() => {
      function setVal(testid, value) {
        const el = document.querySelector('[data-testid="' + testid + '"]');
        const input = el.tagName === 'INPUT' ? el : el.querySelector('input');
        const proto = Object.getPrototypeOf(input);
        const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
        setter.call(input, value);
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('blur', { bubbles: true }));
      }
      setVal('first-name-input', 'Anna');
      setVal('last-name-input', 'Kowalska');
      setVal('email-input', 'anna.kowalska@example.com');
      setVal('confirm-email-input', 'anna.kowalska@example.com');
      setVal('phone-input', '123456789');
      const checkbox = document.querySelector('[data-testid="terms-checkbox"] input') || document.querySelector('[data-testid="terms-checkbox"]');
      checkbox.click();
    })()
  `);
  await sleep(300);

  const payLabel = await evaluate(ws, `document.querySelector('[data-testid="pay-button"]')?.textContent`);
  console.log('PAY LABEL:', payLabel);

  const errorsBeforePay = await evaluate(ws, `
    [...document.querySelectorAll('[data-testid$="-error"]')].map(e => e.getAttribute('data-testid') + ': ' + e.textContent)
  `);
  console.log('FORM ERRORS BEFORE PAY:', errorsBeforePay);

  await evaluate(ws, `document.querySelector('[data-testid="pay-button"]').click()`);
  await sleep(1500);

  const confirmationState = await evaluate(ws, `
    (() => ({
      url: location.href,
      heading: document.querySelector('[data-testid="confirmation-heading"]')?.textContent,
      message: document.querySelector('[data-testid="confirmation-message"]')?.textContent,
    }))()
  `);
  console.log('CONFIRMATION STATE:', JSON.stringify(confirmationState, null, 2));

  await evaluate(ws, `document.querySelector('[data-testid="confirmation-continue-button"]')?.click()`);
  await sleep(500);
  const finalUrl = await evaluate(ws, `location.href`);
  console.log('FINAL URL:', finalUrl);

  console.log('CONSOLE ERRORS/WARNINGS:', consoleErrors);
  console.log('FAILED REQUESTS:', failedRequests);

  process.exit(0);
}

main().catch((e) => {
  console.error('DRIVER ERROR', e);
  process.exit(1);
});

