      return document.querySelector('[data-testid="selected-seats-count"]').textContent;
    })()
  `);
  console.log('AFTER 10 SEATS:', result);
  await evaluate(ws, `
    (() => {
      const extra = [...document.querySelectorAll('[data-testid="seat"][data-state="available"]')][0];
