  await sleep(600);
  await evaluate(ws, `document.querySelector('[data-testid="confirm-button"]').click()`);
  await sleep(600);
  await evaluate(ws, `document.querySelector('[data-testid="pay-button"]').click()`);
  await sleep(400);
  const invalidToast = await evaluate(ws, `document.querySelector('[data-testid="toast"]')?.textContent`);
  console.log('INVALID FORM TOAST:', invalidToast);
  const errors = await evaluate(ws, `[...document.querySelectorAll('[data-testid$="-error"]')].map(e => e.getAttribute('data-testid') + ' => ' + e.textContent)`);
  console.log('ERRORS SHOWN:', JSON.stringify(errors, null, 2));

  // test specific invalid values
  await evaluate(ws, `
    (() => {
      function setVal(testid, value) {
        const el = document.querySelector('[data-testid="' + testid + '"]');
        const input = el.tagName === 'INPUT' ? el : el.querySelector('input');
        const proto = Object.getPrototypeOf(input);
        const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
        setter.call(input, value);
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('blur', { bubbles: true }));
      }
      setVal('first-name-input', 'A');
      setVal('email-input', 'not-an-email');
      setVal('confirm-email-input', 'different@example.com');
